import styled from "styled-components";


export const PropertiesContainer = styled.div`
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 2rem;
    position: relative;

    .right{
        top:50%;
        right:2%;
    }
    

`
export const PaginationCard= styled.div`
    width:4rem;
    height: 4rem;
    border-radius: 50%;
    background: ${({theme}) => theme.colors.primary};

    display: flex;
    align-items: center;
    justify-content: center;
    position: absolute;
  
  


    
`
